SELECT id, name, email, company_name, industry, created_at, updated_at
FROM customers
WHERE id = {{ $json.body.customer_id }}
LIMIT 1;

SELECT id, customer_id, brand_name, target_audience, brand_voice, products_services, default_cta, words_to_use, words_to_avoid, created_at, updated_at
FROM brand_profiles
WHERE customer_id = {{ $('Validate Input').item.json.body.customer_id }}
ORDER BY id DESC;

SELECT id, customer_id, platform, topic, caption, hashtags, status, scheduled_at, created_at
FROM posts
WHERE customer_id = {{ $('Validate Input').item.json.body.customer_id }}
ORDER BY id DESC;

